lemma pderiv_eq_deriv_of_eventuallyEq {b : Fin n} {F : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    {φ : ℝ → ℝ} (h : ∀ᶠ t in 𝓝 (x b), F (coordLine x b t) = φ t) :
    pderiv b F x = deriv φ (x b)

lemma pderiv_eq_of_hasDerivAt {b : Fin n} {F : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    {φ : ℝ → ℝ} {c : ℝ} (h : ∀ᶠ t in 𝓝 (x b), F (coordLine x b t) = φ t)
    (hd : HasDerivAt φ c (x b)) : pderiv b F x = c

lemma pderiv_eq_of_hasDerivAt' {b : Fin n} {F : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    {φ : ℝ → ℝ} {c : ℝ} (h : ∀ t, F (coordLine x b t) = φ t)
    (hd : HasDerivAt φ c (x b)) : pderiv b F x = c

lemma pderiv_congr {b : Fin n} {F G : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (h : ∀ᶠ t in 𝓝 (x b), F (coordLine x b t) = G (coordLine x b t)) :
    pderiv b F x = pderiv b G x

lemma pderiv_finset_sum {ι : Type*} {b : Fin n} {s : Finset ι}
    {F : ι → (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (h : ∀ i ∈ s, DifferentiableAt ℝ (fun t : ℝ => F i (coordLine x b t)) (x b)) :
    pderiv b (fun y => ∑ i ∈ s, F i y) x = ∑ i ∈ s, pderiv b (F i) x

theorem pderiv_eq_fderiv {b : Fin n} {F : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    (hF : DifferentiableAt ℝ F x) :
    pderiv b F x = fderiv ℝ F x (Pi.single b (1 : ℝ))

lemma pderiv_congr_of_mem {n : ℕ} {b : Fin n} {F G : (Fin n → ℝ) → ℝ} {x : Fin n → ℝ}
    {U : Set (Fin n → ℝ)} (hU : ∀ᶠ t in 𝓝 (x b), coordLine x b t ∈ U)
    (hFG : ∀ y ∈ U, F y = G y) : pderiv b F x = pderiv b G x

private lemma hasDerivAt_negSinCos (y : ℝ) :
    HasDerivAt (fun t : ℝ => -(Real.sin t * Real.cos t))
      (Real.sin y ^ 2 - Real.cos y ^ 2) y

private lemma hasDerivAt_negLapseSinSq (r fr y : ℝ) :
    HasDerivAt (fun t : ℝ => -(r * fr * Real.sin t ^ 2))
      (-(2 * r * fr * Real.sin y * Real.cos y)) y

theorem pderiv_flrwMetric {a a₁ : ℝ → ℝ} {x : Fin 4 → ℝ}
    (hd : HasDerivAt a (a₁ (x 0)) (x 0)) (b d c : Fin 4) :
    pderiv b (fun y => flrwMetric a y d c) x = flrwDMetric a a₁ x b d c

theorem christoffel_flrw {a a₁ : ℝ → ℝ} {x : Fin 4 → ℝ}
    (hd : HasDerivAt a (a₁ (x 0)) (x 0)) (ha : a (x 0) ≠ 0) (c d e : Fin 4) :
    christoffel (flrwMetric a) x c d e = flrwGamma a a₁ x c d e

private lemma hasDerivAt_scaleProd (hd1 : HasDerivAt a (a₁ (x 0)) (x 0))
    (hd2 : HasDerivAt a₁ (a₂ (x 0)) (x 0)) :
    HasDerivAt (fun t => a t * a₁ t) (a (x 0) * a₂ (x 0) + a₁ (x 0) ^ 2) (x 0)

theorem riemann_eq_zero_of_christoffel_eq_zero {g : MetricFn n}
    (h : ∀ y a b c, christoffel g y a b c = 0) (x : Fin n → ℝ) (a b c d : Fin n) :
    riemann g x a b c d = 0

theorem sum_inv_mul_metric {g : MetricFn n} (hg : IsSymmetricMetric g) {x : Fin n → ℝ}
    (hx : IsUnit (g x).det) :
    ∑ b : Fin n, ∑ d : Fin n, (g x)⁻¹ b d * g x b d = (n : ℝ)

theorem pderiv_ssMetric {f f₁ : ℝ → ℝ} {x : Fin 4 → ℝ}
    (hd : HasDerivAt f (f₁ (x 1)) (x 1)) (hf : f (x 1) ≠ 0) (b d c : Fin 4) :
    pderiv b (fun y => ssMetric f y d c) x = ssDMetric f f₁ x b d c

theorem einstein_ss_of_scalarCurvature_eq_zero {f : ℝ → ℝ} {x : Fin 4 → ℝ}
    (h : scalarCurvature (ssMetric f) x = 0) (b d : Fin 4) :
    einstein (ssMetric f) x b d = ricci (ssMetric f) x b d

private lemma hasDerivAt_vNegConstMulSinSq (c y : ℝ) :
    HasDerivAt (fun t : ℝ => -(c * Real.sin t ^ 2))
      (-(2 * c * Real.sin y * Real.cos y)) y

private lemma hasDerivAt_vNegSinCos (y : ℝ) :
    HasDerivAt (fun t : ℝ => -(Real.sin t * Real.cos t))
      (Real.sin y ^ 2 - Real.cos y ^ 2) y

theorem pderiv_vaidyaMetric {m m₁ : ℝ → ℝ} {x : Fin 4 → ℝ}
    (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (hr : x 1 ≠ 0) (b d c : Fin 4) :
    pderiv b (fun y => vaidyaMetric m y d c) x = vDMetric m m₁ x b d c

private theorem christoffel_vaidya_v (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (hr : x 1 ≠ 0)
    (hs : Real.sin (x 2) ≠ 0) (b c : Fin 4) :
    christoffel (vaidyaMetric m) x 0 b c = vGamma m m₁ x 0 b c

private theorem christoffel_vaidya_r (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (hr : x 1 ≠ 0)
    (hs : Real.sin (x 2) ≠ 0) (b c : Fin 4) :
    christoffel (vaidyaMetric m) x 1 b c = vGamma m m₁ x 1 b c

private theorem christoffel_vaidya_th (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (hr : x 1 ≠ 0)
    (hs : Real.sin (x 2) ≠ 0) (b c : Fin 4) :
    christoffel (vaidyaMetric m) x 2 b c = vGamma m m₁ x 2 b c

private theorem christoffel_vaidya_ph (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (hr : x 1 ≠ 0)
    (hs : Real.sin (x 2) ≠ 0) (b c : Fin 4) :
    christoffel (vaidyaMetric m) x 3 b c = vGamma m m₁ x 3 b c

private lemma vGamma_coordLine_of_ne (m m₁ : ℝ → ℝ) (x : Fin 4 → ℝ) (b : Fin 4)
    (h0 : (0 : Fin 4) ≠ b) (h1 : (1 : Fin 4) ≠ b) (h2 : (2 : Fin 4) ≠ b) (t : ℝ) :
    vGamma m m₁ (coordLine x b t) = vGamma m m₁ x

theorem pderiv_vGamma_v_row {m m₁ : ℝ → ℝ} {x : Fin 4 → ℝ}
    (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (c d : Fin 4) :
    pderiv 0 (fun y => vGamma m m₁ y 0 c d) x = vDGammaV m₁ x c d

theorem pderiv_vGamma_v_trace {m m₁ : ℝ → ℝ} {x : Fin 4 → ℝ}
    (hd : HasDerivAt m (m₁ (x 0)) (x 0)) (a b : Fin 4) :
    pderiv 0 (fun y => vGamma m m₁ y a a b) x = vDGammaVtr m₁ x a b
